using MediatR;
using TheMathAndScienceAcademy.Application.Abstractions;
using TheMathAndScienceAcademy.Application.Common;
using TheMathAndScienceAcademy.Domain.Entities;
using TheMathAndScienceAcademy.Domain.Repositories;

namespace TheMathAndScienceAcademy.Application.Features.Teachers;

public record TeacherDto(Guid Id, string FullName, string EmployeeNumber, string? Email, string? PhoneNumber, DateTime? DateOfBirth, string? Gender, string? Address, DateTime HireDate, string Status, Guid AcademyId, string? AcademyName, Guid? UserId, string? UserName, bool LoginEnabled, bool MustChangePassword, bool HasProfilePhoto, DateTime? ProfilePhotoUpdatedAt);
public class CreateTeacherCommand : IRequest<ApiResponse<TeacherDto>> { public string FullName { get; set; } = ""; public string EmployeeNumber { get; set; } = ""; public string? Email { get; set; } public string? PhoneNumber { get; set; } public DateTime? DateOfBirth { get; set; } public string? Gender { get; set; } public string? Address { get; set; } public DateTime HireDate { get; set; } = DateTime.UtcNow.Date; public string Status { get; set; } = "Active"; public Guid? AcademyId { get; set; } }
public class UpdateTeacherCommand : CreateTeacherCommand { public Guid Id { get; set; } }
public record DeleteTeacherCommand(Guid Id) : IRequest<ApiResponse<bool>>;
public record GetTeachersQuery : IRequest<ApiResponse<List<TeacherDto>>>;
public record GetTeacherQuery(Guid Id) : IRequest<ApiResponse<TeacherDto>>;
public record GetMyTeacherQuery : IRequest<ApiResponse<TeacherDto>>;
public record CreateTeacherAccountCommand(Guid Id) : IRequest<ApiResponse<TeacherDto>>;
public record ResendTeacherCredentialsCommand(Guid Id) : IRequest<ApiResponse<bool>>;

public class TeacherHandlers : ResponseHandler,
    IRequestHandler<CreateTeacherCommand, ApiResponse<TeacherDto>>, IRequestHandler<UpdateTeacherCommand, ApiResponse<TeacherDto>>,
    IRequestHandler<DeleteTeacherCommand, ApiResponse<bool>>, IRequestHandler<GetTeachersQuery, ApiResponse<List<TeacherDto>>>,
    IRequestHandler<GetTeacherQuery, ApiResponse<TeacherDto>>, IRequestHandler<GetMyTeacherQuery, ApiResponse<TeacherDto>>,
    IRequestHandler<CreateTeacherAccountCommand, ApiResponse<TeacherDto>>, IRequestHandler<ResendTeacherCredentialsCommand, ApiResponse<bool>>
{
    private readonly ITeacherRepository _teachers; private readonly IAcademyRepository _academies; private readonly IUserRepository _users; private readonly IRoleRepository _roles; private readonly IPermissionRepository _permissions; private readonly IRolePermissionRepository _links; private readonly IRolePermissionSyncService _sync; private readonly IAcademyScopeService _scope; private readonly ICurrentUserService _current; private readonly IPasswordHasher _hasher; private readonly ITemporaryPasswordGenerator _passwords; private readonly IEmailService _email; private readonly ITransactionService _transaction; private readonly IProfilePhotoStorage _photos;
    public TeacherHandlers(ITeacherRepository teachers, IAcademyRepository academies, IUserRepository users, IRoleRepository roles, IPermissionRepository permissions, IRolePermissionRepository links, IRolePermissionSyncService sync, IAcademyScopeService scope, ICurrentUserService current, IPasswordHasher hasher, ITemporaryPasswordGenerator passwords, IEmailService email, ITransactionService transaction, IProfilePhotoStorage photos) { _teachers=teachers; _academies=academies; _users=users; _roles=roles; _permissions=permissions; _links=links; _sync=sync; _scope=scope; _current=current; _hasher=hasher; _passwords=passwords; _email=email; _transaction=transaction; _photos=photos; }
    public async Task<ApiResponse<TeacherDto>> Handle(CreateTeacherCommand r, CancellationToken ct) { var academy=await Resolve(r.AcademyId); if(academy is null)return BadRequest<TeacherDto>(ResponseMessages.AcademySelectionRequired); if(await _teachers.GetByEmployeeNumberAsync(academy,r.EmployeeNumber.Trim()) is not null)return BadRequest<TeacherDto>(ResponseMessages.TeacherAlreadyExists); var t=new Teacher{FullName=r.FullName.Trim(),EmployeeNumber=r.EmployeeNumber.Trim(),Email=Email(r.Email),PhoneNumber=Text(r.PhoneNumber),DateOfBirth=Date(r.DateOfBirth),Gender=Text(r.Gender),Address=Text(r.Address),HireDate=Date(r.HireDate)!.Value,Status=Status(r.Status),AcademyId=academy}; var created=await _teachers.CreateAsync(t); return created is null?BadRequest<TeacherDto>(ResponseMessages.TeacherNotFound):Created(await Dto(created),ResponseMessages.TeacherCreated); }
    public async Task<ApiResponse<TeacherDto>> Handle(UpdateTeacherCommand r, CancellationToken ct) { var t=await _teachers.GetByIdAsync(r.Id.ToString()); if(t is null)return NotFound<TeacherDto>(ResponseMessages.TeacherNotFound); if(!await Can(t.AcademyId))return BadRequest<TeacherDto>(ResponseMessages.Forbidden); if(await _teachers.GetByEmployeeNumberAsync(t.AcademyId,r.EmployeeNumber.Trim(),t.Id) is not null)return BadRequest<TeacherDto>(ResponseMessages.TeacherAlreadyExists); t.FullName=r.FullName.Trim();t.EmployeeNumber=r.EmployeeNumber.Trim();t.Email=Email(r.Email);t.PhoneNumber=Text(r.PhoneNumber);t.DateOfBirth=Date(r.DateOfBirth);t.Gender=Text(r.Gender);t.Address=Text(r.Address);t.HireDate=Date(r.HireDate)!.Value;t.Status=Status(r.Status);t.UpdatedAt=DateTime.UtcNow; if(t.UserId is not null){var u=await _users.GetByIdAsync(t.UserId);if(u is not null){u.Name=t.FullName;u.Email=t.Email??u.Email;await _users.UpdateAsync(u);}} await _teachers.UpdateAsync(t);return Updated(await Dto(t),ResponseMessages.TeacherUpdated); }
    public async Task<ApiResponse<bool>> Handle(DeleteTeacherCommand r,CancellationToken ct){var t=await _teachers.GetByIdAsync(r.Id.ToString());if(t is null)return NotFound<bool>(ResponseMessages.TeacherNotFound);if(!await Can(t.AcademyId))return BadRequest<bool>(ResponseMessages.Forbidden);if(t.UserId is not null)await _users.DeleteAsync(t.UserId);await _teachers.DeleteAsync(t.Id);await _photos.DeleteAsync(t.ProfilePhotoKey,ct);return Deleted<bool>(ResponseMessages.TeacherDeleted);}
    public async Task<ApiResponse<List<TeacherDto>>> Handle(GetTeachersQuery r,CancellationToken ct){var s=await _scope.GetScopeAsync();if(!s.IsValid||s.AcademyId is null)return BadRequest<List<TeacherDto>>(ResponseMessages.AcademySelectionRequired);var result=new List<TeacherDto>();foreach(var t in await _teachers.GetByAcademyIdAsync(s.AcademyId))result.Add(await Dto(t));return Success(result);}
    public async Task<ApiResponse<TeacherDto>> Handle(GetTeacherQuery r,CancellationToken ct){var t=await _teachers.GetByIdAsync(r.Id.ToString());if(t is null)return NotFound<TeacherDto>(ResponseMessages.TeacherNotFound);if(!await Can(t.AcademyId))return BadRequest<TeacherDto>(ResponseMessages.Forbidden);return Success(await Dto(t));}
    public async Task<ApiResponse<TeacherDto>> Handle(GetMyTeacherQuery r,CancellationToken ct){if(_current.UserId is null)return BadRequest<TeacherDto>(ResponseMessages.Unauthorized);var t=await _teachers.GetByUserIdAsync(_current.UserId);if(t is null)return NotFound<TeacherDto>(ResponseMessages.TeacherNotFound);if(!await Can(t.AcademyId))return BadRequest<TeacherDto>(ResponseMessages.Forbidden);return Success(await Dto(t));}
    public async Task<ApiResponse<TeacherDto>> Handle(CreateTeacherAccountCommand r,CancellationToken ct)=>await Provision(r.Id.ToString());
    public async Task<ApiResponse<bool>> Handle(ResendTeacherCredentialsCommand r,CancellationToken ct){var t=await _teachers.GetByIdAsync(r.Id.ToString());if(t is null)return NotFound<bool>(ResponseMessages.TeacherNotFound);if(!await Can(t.AcademyId))return BadRequest<bool>(ResponseMessages.Forbidden);if(t.UserId is null)return BadRequest<bool>(ResponseMessages.TeacherEmailRequired);var u=await _users.GetByIdAsync(t.UserId);var a=await _academies.GetByIdAsync(Guid.Parse(t.AcademyId));if(u is null||a is null)return NotFound<bool>(ResponseMessages.TeacherNotFound);var p=_passwords.Generate();u.PasswordHash=_hasher.HashPassword(p);u.MustChangePassword=true;u.IsActive=false;await _users.UpdateAsync(u);try{await _email.SendAsync(u.Email,$"Your teacher account for {a.Name}",$"Dear {t.FullName},\n\nEmail: {u.Email}\nTemporary password: {p}\n\nPlease change your password after signing in.");u.IsActive=true;u.CredentialsSentAt=DateTime.UtcNow;await _users.UpdateAsync(u);return Success(true,ResponseMessages.TeacherCredentialsResent);}catch{return BadRequest<bool>(ResponseMessages.StudentCredentialsEmailFailed);}}
    private async Task<ApiResponse<TeacherDto>> Provision(string id){var t=await _teachers.GetByIdAsync(id);if(t is null)return NotFound<TeacherDto>(ResponseMessages.TeacherNotFound);if(!await Can(t.AcademyId))return BadRequest<TeacherDto>(ResponseMessages.Forbidden);if(t.UserId is not null)return BadRequest<TeacherDto>(ResponseMessages.TeacherAccountAlreadyExists);if(t.Email is null)return BadRequest<TeacherDto>(ResponseMessages.TeacherEmailRequired);if(await _users.GetByEmailAsync(t.Email) is not null)return BadRequest<TeacherDto>(ResponseMessages.StudentUserAlreadyExists);var academy=await _academies.GetByIdAsync(Guid.Parse(t.AcademyId));if(academy is null)return NotFound<TeacherDto>(ResponseMessages.AcademyNotFound);var p=_passwords.Generate();try{await _transaction.ExecuteAsync(async()=>{var role=await _roles.GetByNameAsync("Teacher",t.AcademyId)??await _roles.CreateAsync(new Role{Name="Teacher",Description="Teacher login role for this academy.",AcademyId=t.AcademyId});if(role is null)throw new InvalidOperationException(ResponseMessages.TeacherRoleCreateFailed);await _sync.SyncRoleAsync(role.Id);foreach(var permissionName in new[]{"teacher.self-view","teaching-assignment.self-view"}){var permission=await _permissions.GetByNameAsync(permissionName);if(permission is not null)await _links.AssignPermissionAsync(role.Id,permission.Id);}var u=new User{Name=t.FullName,Email=t.Email,PasswordHash=_hasher.HashPassword(p),RoleId=role.Id,AcademyId=t.AcademyId,IsActive=false,MustChangePassword=true};await _users.CreateAsync(u);t.UserId=u.Id;t.UpdatedAt=DateTime.UtcNow;await _teachers.UpdateAsync(t);return true;});await _email.SendAsync(t.Email,$"Your teacher account for {academy.Name}",$"Dear {t.FullName},\n\nEmail: {t.Email}\nTemporary password: {p}\n\nPlease change your password after signing in.");var linked=await _users.GetByEmailAsync(t.Email);if(linked is not null){linked.IsActive=true;linked.CredentialsSentAt=DateTime.UtcNow;await _users.UpdateAsync(linked);}return Created(await Dto(t),ResponseMessages.TeacherAccountCreated);}catch(InvalidOperationException e){return BadRequest<TeacherDto>(e.Message);}catch{return BadRequest<TeacherDto>(ResponseMessages.TeacherCredentialsPending);}}
    private async Task<string?> Resolve(Guid? requested){var s=await _scope.GetScopeAsync();if(!s.IsValid||s.AcademyId is null)return null;if(requested.HasValue&&!requested.Value.ToString().Equals(s.AcademyId,StringComparison.OrdinalIgnoreCase))return null;return s.AcademyId;}
    private async Task<bool> Can(string academy){var s=await _scope.GetScopeAsync();return s.IsValid&&string.Equals(s.AcademyId,academy,StringComparison.OrdinalIgnoreCase);}
    private async Task<TeacherDto> Dto(Teacher t){var a=await _academies.GetByIdAsync(Guid.Parse(t.AcademyId));var u=t.UserId is null?null:await _users.GetByIdAsync(t.UserId);return new(Guid.Parse(t.Id),t.FullName,t.EmployeeNumber,t.Email,t.PhoneNumber,t.DateOfBirth,t.Gender,t.Address,t.HireDate,t.Status,Guid.Parse(t.AcademyId),a?.Name,u is null?null:Guid.Parse(u.Id),u?.Name,u?.IsActive==true,u?.MustChangePassword==true,!string.IsNullOrWhiteSpace(t.ProfilePhotoKey),t.ProfilePhotoUpdatedAt);}
    private static string? Text(string? x)=>string.IsNullOrWhiteSpace(x)?null:x.Trim();private static string? Email(string? x)=>string.IsNullOrWhiteSpace(x)?null:x.Trim().ToLowerInvariant();private static DateTime? Date(DateTime? x)=>x.HasValue?DateTime.SpecifyKind(x.Value.Date,DateTimeKind.Utc):null;private static string Status(string x)=>x.Equals("Inactive",StringComparison.OrdinalIgnoreCase)?"Inactive":"Active";
}
